mapper.select:
SELECT p.po_id, p.po_no, p.po_no AS order_id, p.branch_code, b.name AS branch_name, DATE_FORMAT(p.request_date, '%Y-%m-%d %H:%i') AS created_at, COUNT(DISTINCT pod.po_detail_id) AS item_count, COALESCE(CAST(SUM(pod.requested_qty) AS SIGNED), 0) AS total_qty, p.total_material_cnt, p.total_amount, p.reject_reason, p.status AS status_code, CASE p.status WHEN 'PENDING' THEN '전송' WHEN 'APPROVED' THEN '승인' WHEN 'REJECTED' THEN '반려' ELSE '전송' END AS status, CASE p.status WHEN 'PENDING' THEN '전송' WHEN 'APPROVED' THEN '승인' WHEN 'REJECTED' THEN '반려' ELSE '전송' END AS status_key, CONCAT(#{contextPath}, '/branch/place_order/', CASE p.status WHEN 'APPROVED' THEN 'approval_detail.jsp' WHEN 'REJECTED' THEN 'rejection_detail.jsp' ELSE 'request_detail.jsp' END) AS detail_url, CASE WHEN p.status = 'PENDING' THEN CONCAT(#{contextPath}, '/branch/place_order/cancel_request.jsp') ELSE NULL END AS cancel_url FROM place_order p JOIN branch b ON b.branch_code = p.branch_code LEFT JOIN place_order_detail pod ON pod.po_id = p.po_id WHERE p.branch_code = #{branchCode}
AND DATE(p.request_date) >= #{startDate}
AND DATE(p.request_date) <= #{endDate}
AND ( CASE p.status WHEN 'PENDING' THEN '전송' WHEN 'APPROVED' THEN '승인' WHEN 'REJECTED' THEN '반려' ELSE '전송' END ) = #{status}
GROUP BY p.po_id, p.po_no, p.branch_code, b.name, p.request_date, p.total_material_cnt, p.total_amount, p.reject_reason, p.status ORDER BY p.request_date DESC, p.po_id DESC

mapper.update:
UPDATE place_order
SET status = #{status},
    reject_reason = #{rejectReason}
WHERE po_no = #{poNo}
